/bin/bash -lc "python - <<'PY'
from ansible.utils import encrypt
p=encrypt.PasslibHash('bcrypt')
for ident in ('2','2a','2y','2b'):
    try:
        v=p.crypt_algo.using(ident=ident,rounds=12,salt='123456789012345678901u').hash('foo')
        print(ident,repr(v[:10]))
    except Exception as e:
        print(ident,type(e).__name__,str(e)[:100])
PY"

